CREATE TABLE eam_maintenance_type (id BIGINT NOT NULL COMMENT '业务ID',tenant_id BIGINT NOT NULL COMMENT '租户ID',code VARCHAR(64) NOT NULL COMMENT '编号',name VARCHAR(150) NOT NULL COMMENT '名称',department_id BIGINT NULL COMMENT '所属部门ID',creator_id BIGINT NOT NULL COMMENT '创建人ID',row_version INT NOT NULL DEFAULT 0 COMMENT '乐观锁版本',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',`period_count` INT NOT NULL COMMENT '周期数',`period_unit` VARCHAR(8) NOT NULL COMMENT '周期单位',`symbol` VARCHAR(40) NOT NULL COMMENT '保留的类型标记',`is_system` TINYINT NOT NULL COMMENT '系统预置类型',`enabled` TINYINT NOT NULL COMMENT '启用状态',`remark` TEXT NOT NULL COMMENT '说明',PRIMARY KEY(id),UNIQUE KEY uq_eam_maintenance_type(tenant_id,code),INDEX ix_eam_maintenance_type_page(tenant_id,created_at,id),INDEX ix_eam_maintenance_type_org(tenant_id,department_id,created_at,id)) COMMENT='保养类型';

INSERT INTO eam_maintenance_type (id,tenant_id,code,name,department_id,creator_id,row_version,created_at,updated_at,`period_count`,`period_unit`,`symbol`,`is_system`,`enabled`,`remark`) SELECT id,tenant_id,code,name,department_id,creator_id,row_version,created_at,updated_at,COALESCE(CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.period')),'null'),'') AS SIGNED),1),COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.unit')),'null'),''),'月'),COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.symbol')),'null'),''),''),CASE WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.system')),'null'),'') IN ('true','1') THEN 1 WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.system')),'null'),'') IN ('false','0') THEN 0 ELSE 0 END,CASE WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.enabled')),'null'),'') IN ('true','1') THEN 1 WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.enabled')),'null'),'') IN ('false','0') THEN 0 ELSE 1 END,COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.remark')),'null'),''),'') FROM eam_maintenance_definition WHERE kind='types';

CREATE TABLE eam_maintenance_standard (id BIGINT NOT NULL COMMENT '业务ID',tenant_id BIGINT NOT NULL COMMENT '租户ID',code VARCHAR(64) NOT NULL COMMENT '编号',name VARCHAR(150) NOT NULL COMMENT '名称',department_id BIGINT NULL COMMENT '所属部门ID',creator_id BIGINT NOT NULL COMMENT '创建人ID',row_version INT NOT NULL DEFAULT 0 COMMENT '乐观锁版本',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',`enabled` TINYINT NOT NULL COMMENT '启用状态',`remark` TEXT NOT NULL COMMENT '说明',PRIMARY KEY(id),UNIQUE KEY uq_eam_maintenance_standard(tenant_id,code),INDEX ix_eam_maintenance_standard_page(tenant_id,created_at,id),INDEX ix_eam_maintenance_standard_org(tenant_id,department_id,created_at,id)) COMMENT='保养标准';

INSERT INTO eam_maintenance_standard (id,tenant_id,code,name,department_id,creator_id,row_version,created_at,updated_at,`enabled`,`remark`) SELECT id,tenant_id,code,name,department_id,creator_id,row_version,created_at,updated_at,CASE WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.enabled')),'null'),'') IN ('true','1') THEN 1 WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.enabled')),'null'),'') IN ('false','0') THEN 0 ELSE 1 END,COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.remark')),'null'),''),'') FROM eam_maintenance_definition WHERE kind='standards';

CREATE TABLE eam_maintenance_plan (id BIGINT NOT NULL COMMENT '业务ID',tenant_id BIGINT NOT NULL COMMENT '租户ID',code VARCHAR(64) NOT NULL COMMENT '编号',name VARCHAR(150) NOT NULL COMMENT '名称',department_id BIGINT NULL COMMENT '所属部门ID',creator_id BIGINT NOT NULL COMMENT '创建人ID',row_version INT NOT NULL DEFAULT 0 COMMENT '乐观锁版本',created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '更新时间',`enabled` TINYINT NOT NULL COMMENT '启用状态',`remark` TEXT NOT NULL COMMENT '说明',`calculation_mode` VARCHAR(24) NOT NULL COMMENT '下次日期计算方式',`advance_days` INT NOT NULL COMMENT '提前生成天数',`remind_days` INT NOT NULL COMMENT '提前提醒天数',`auto_fill` VARCHAR(24) NOT NULL COMMENT '结果自动填写方式',`scan_start` TINYINT NOT NULL COMMENT '开始是否扫码',`review_mode` VARCHAR(40) NOT NULL COMMENT '验收方式',`review_rule` VARCHAR(100) NOT NULL COMMENT '验收规则',PRIMARY KEY(id),UNIQUE KEY uq_eam_maintenance_plan(tenant_id,code),INDEX ix_eam_maintenance_plan_page(tenant_id,created_at,id),INDEX ix_eam_maintenance_plan_org(tenant_id,department_id,created_at,id)) COMMENT='保养计划';

INSERT INTO eam_maintenance_plan (id,tenant_id,code,name,department_id,creator_id,row_version,created_at,updated_at,`enabled`,`remark`,`calculation_mode`,`advance_days`,`remind_days`,`auto_fill`,`scan_start`,`review_mode`,`review_rule`) SELECT id,tenant_id,code,name,department_id,creator_id,row_version,created_at,updated_at,CASE WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.enabled')),'null'),'') IN ('true','1') THEN 1 WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.enabled')),'null'),'') IN ('false','0') THEN 0 ELSE 1 END,COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.remark')),'null'),''),''),COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.calculation')),'null'),''),'固定间隔'),COALESCE(CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.advanceDays')),'null'),'') AS SIGNED),0),COALESCE(CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.remindDays')),'null'),'') AS SIGNED),0),COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.autoFill')),'null'),''),'无'),CASE WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.scanStart')),'null'),'') IN ('true','1') THEN 1 WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.scanStart')),'null'),'') IN ('false','0') THEN 0 ELSE 0 END,COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.reviewMode')),'null'),''),''),COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.reviewRule')),'null'),''),'') FROM eam_maintenance_definition WHERE kind='plans';

CREATE TABLE eam_maintenance_standard_person (tenant_id BIGINT NOT NULL COMMENT '租户ID',standard_id BIGINT NOT NULL COMMENT '所属业务ID',role_code VARCHAR(16) NOT NULL COMMENT 'owner/reviewer',user_id BIGINT NOT NULL COMMENT '人员ID',sort_no INT NOT NULL COMMENT '顺序',PRIMARY KEY(tenant_id,standard_id,role_code,user_id),INDEX ix_standard_person(tenant_id,user_id),FOREIGN KEY(standard_id) REFERENCES eam_maintenance_standard(id) ON DELETE CASCADE) COMMENT='保养standard人员关系';

INSERT INTO eam_maintenance_standard_person SELECT d.tenant_id,d.id,'owner',j.user_id,MIN(j.sort_no) FROM eam_maintenance_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.owners'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,user_id BIGINT PATH '$' ERROR ON ERROR)) j WHERE d.kind='standards' GROUP BY d.tenant_id,d.id,j.user_id;

INSERT INTO eam_maintenance_standard_person SELECT d.tenant_id,d.id,'reviewer',j.user_id,MIN(j.sort_no) FROM eam_maintenance_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.reviewers'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,user_id BIGINT PATH '$' ERROR ON ERROR)) j WHERE d.kind='standards' GROUP BY d.tenant_id,d.id,j.user_id;

CREATE TABLE eam_maintenance_plan_person (tenant_id BIGINT NOT NULL COMMENT '租户ID',plan_id BIGINT NOT NULL COMMENT '所属业务ID',role_code VARCHAR(16) NOT NULL COMMENT 'owner/reviewer',user_id BIGINT NOT NULL COMMENT '人员ID',sort_no INT NOT NULL COMMENT '顺序',PRIMARY KEY(tenant_id,plan_id,role_code,user_id),INDEX ix_plan_person(tenant_id,user_id),FOREIGN KEY(plan_id) REFERENCES eam_maintenance_plan(id) ON DELETE CASCADE) COMMENT='保养plan人员关系';

INSERT INTO eam_maintenance_plan_person SELECT d.tenant_id,d.id,'owner',j.user_id,MIN(j.sort_no) FROM eam_maintenance_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.owners'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,user_id BIGINT PATH '$' ERROR ON ERROR)) j WHERE d.kind='plans' GROUP BY d.tenant_id,d.id,j.user_id;

INSERT INTO eam_maintenance_plan_person SELECT d.tenant_id,d.id,'reviewer',j.user_id,MIN(j.sort_no) FROM eam_maintenance_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.reviewers'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,user_id BIGINT PATH '$' ERROR ON ERROR)) j WHERE d.kind='plans' GROUP BY d.tenant_id,d.id,j.user_id;

CREATE TABLE eam_maintenance_standard_equipment (tenant_id BIGINT NOT NULL COMMENT '租户ID',standard_id BIGINT NOT NULL COMMENT '标准ID',equipment_id BIGINT NOT NULL COMMENT '关联对象ID',sort_no INT NOT NULL COMMENT '顺序',PRIMARY KEY(tenant_id,standard_id,equipment_id),INDEX ix_standard_equipment_target(tenant_id,equipment_id),FOREIGN KEY(standard_id) REFERENCES eam_maintenance_standard(id) ON DELETE CASCADE) COMMENT='保养标准适用equipment';

INSERT INTO eam_maintenance_standard_equipment SELECT d.tenant_id,d.id,j.target_id,MIN(j.sort_no) FROM eam_maintenance_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.equipmentIds'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,target_id BIGINT PATH '$' ERROR ON ERROR)) j WHERE d.kind='standards' GROUP BY d.tenant_id,d.id,j.target_id;

CREATE TABLE eam_maintenance_standard_category (tenant_id BIGINT NOT NULL COMMENT '租户ID',standard_id BIGINT NOT NULL COMMENT '标准ID',category_id BIGINT NOT NULL COMMENT '关联对象ID',sort_no INT NOT NULL COMMENT '顺序',PRIMARY KEY(tenant_id,standard_id,category_id),INDEX ix_standard_category_target(tenant_id,category_id),FOREIGN KEY(standard_id) REFERENCES eam_maintenance_standard(id) ON DELETE CASCADE) COMMENT='保养标准适用category';

INSERT INTO eam_maintenance_standard_category SELECT d.tenant_id,d.id,j.target_id,MIN(j.sort_no) FROM eam_maintenance_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.categoryIds'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,target_id BIGINT PATH '$' ERROR ON ERROR)) j WHERE d.kind='standards' GROUP BY d.tenant_id,d.id,j.target_id;

CREATE TABLE eam_maintenance_standard_category_label (tenant_id BIGINT NOT NULL,standard_id BIGINT NOT NULL,label_kind VARCHAR(16) NOT NULL COMMENT 'display/legacy',sort_no INT NOT NULL,name_snapshot VARCHAR(255) NOT NULL COMMENT '类别名称快照或待确认历史名称',PRIMARY KEY(tenant_id,standard_id,label_kind,sort_no),FOREIGN KEY(standard_id) REFERENCES eam_maintenance_standard(id) ON DELETE CASCADE) COMMENT='类别展示及未能确定的历史名称，不作为ID关联';

INSERT INTO eam_maintenance_standard_category_label SELECT d.tenant_id,d.id,'display',j.sort_no,j.name FROM eam_maintenance_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.categoryNames'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,name VARCHAR(255) PATH '$')) j WHERE d.kind='standards';

INSERT INTO eam_maintenance_standard_category_label SELECT d.tenant_id,d.id,'legacy',j.sort_no,j.name FROM eam_maintenance_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.legacyCategoryNames'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,name VARCHAR(255) PATH '$')) j WHERE d.kind='standards';

CREATE TABLE eam_maintenance_standard_item (tenant_id BIGINT NOT NULL COMMENT '租户ID',standard_id BIGINT NOT NULL COMMENT '标准ID',item_key VARCHAR(128) NOT NULL COMMENT '稳定项目ID',sort_no INT NOT NULL COMMENT '顺序',`code` VARCHAR(64) NOT NULL COMMENT '项目编号',`module_name` VARCHAR(150) NOT NULL COMMENT '保养部位',`name` VARCHAR(200) NOT NULL COMMENT '项目名称',`content` TEXT NOT NULL COMMENT '保养内容',`type_id` BIGINT NULL COMMENT '保养类型ID',`value_type` VARCHAR(16) NOT NULL COMMENT '结果类型',`lower_bound` DECIMAL(30,8) NULL COMMENT '数值下限',`upper_bound` DECIMAL(30,8) NULL COMMENT '数值上限',`required` TINYINT NOT NULL COMMENT '必填',`photo_required` TINYINT NOT NULL COMMENT '必须拍照',`remark` TEXT NOT NULL COMMENT '说明',`spare_description` TEXT NOT NULL COMMENT '备件要求说明',PRIMARY KEY(tenant_id,standard_id,item_key),INDEX ix_maintenance_item_type(tenant_id,type_id),FOREIGN KEY(standard_id) REFERENCES eam_maintenance_standard(id) ON DELETE CASCADE) COMMENT='保养标准项目';

INSERT INTO eam_maintenance_standard_item SELECT d.tenant_id,d.id,JSON_UNQUOTE(JSON_EXTRACT(j.item,'$.id')),j.sort_no,COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.item,'$.code')),'null'),''),''),COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.item,'$.module')),'null'),''),''),COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.item,'$.name')),'null'),''),''),COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.item,'$.content')),'null'),''),''),COALESCE(CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.item,'$.typeId')),'null'),'') AS SIGNED),NULL),COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.item,'$.valueType')),'null'),''),'文本'),COALESCE(CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.item,'$.lower')),'null'),'') AS DECIMAL(30,8)),NULL),COALESCE(CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.item,'$.upper')),'null'),'') AS DECIMAL(30,8)),NULL),CASE WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.item,'$.required')),'null'),'') IN ('true','1') THEN 1 WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.item,'$.required')),'null'),'') IN ('false','0') THEN 0 ELSE 0 END,CASE WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.item,'$.photoRequired')),'null'),'') IN ('true','1') THEN 1 WHEN NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.item,'$.photoRequired')),'null'),'') IN ('false','0') THEN 0 ELSE 0 END,COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.item,'$.remark')),'null'),''),''),COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(j.item,'$.spares')),'null'),''),'') FROM eam_maintenance_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.items'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,item JSON PATH '$')) j WHERE d.kind='standards';

CREATE TABLE eam_maintenance_item_option (tenant_id BIGINT NOT NULL,standard_id BIGINT NOT NULL,item_key VARCHAR(128) NOT NULL,sort_no INT NOT NULL,option_value VARCHAR(500) NOT NULL COMMENT '选项值',normal_value TINYINT NOT NULL COMMENT '是否正常',PRIMARY KEY(tenant_id,standard_id,item_key,sort_no),FOREIGN KEY(tenant_id,standard_id,item_key) REFERENCES eam_maintenance_standard_item(tenant_id,standard_id,item_key) ON DELETE CASCADE) COMMENT='保养项目option明细';

INSERT INTO eam_maintenance_item_option SELECT d.tenant_id,d.id,JSON_UNQUOTE(JSON_EXTRACT(j.item,'$.id')),v.sort_no,JSON_UNQUOTE(v.value),CASE WHEN JSON_CONTAINS(JSON_EXTRACT(j.item,'$.normalOptions'),v.value) THEN 1 ELSE 0 END FROM eam_maintenance_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.items'),JSON_ARRAY()),'$[*]' COLUMNS(item JSON PATH '$')) j JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(j.item,'$.options'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,value JSON PATH '$')) v WHERE d.kind='standards';

CREATE TABLE eam_maintenance_item_file (tenant_id BIGINT NOT NULL,standard_id BIGINT NOT NULL,item_key VARCHAR(128) NOT NULL,sort_no INT NOT NULL,file_id VARCHAR(64) NOT NULL COMMENT '文件ID',name_snapshot VARCHAR(255) NOT NULL,content_type VARCHAR(150) NOT NULL,size_bytes BIGINT NOT NULL,url_snapshot VARCHAR(1000) NOT NULL,PRIMARY KEY(tenant_id,standard_id,item_key,sort_no),FOREIGN KEY(tenant_id,standard_id,item_key) REFERENCES eam_maintenance_standard_item(tenant_id,standard_id,item_key) ON DELETE CASCADE) COMMENT='保养项目file明细';

INSERT INTO eam_maintenance_item_file SELECT d.tenant_id,d.id,JSON_UNQUOTE(JSON_EXTRACT(j.item,'$.id')),v.sort_no,JSON_UNQUOTE(JSON_EXTRACT(v.value,'$.id')),COALESCE(JSON_UNQUOTE(JSON_EXTRACT(v.value,'$.name')),''),COALESCE(JSON_UNQUOTE(JSON_EXTRACT(v.value,'$.contentType')),''),COALESCE(JSON_EXTRACT(v.value,'$.size'),0),COALESCE(JSON_UNQUOTE(JSON_EXTRACT(v.value,'$.url')),'') FROM eam_maintenance_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.items'),JSON_ARRAY()),'$[*]' COLUMNS(item JSON PATH '$')) j JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(j.item,'$.references'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,value JSON PATH '$')) v WHERE d.kind='standards';

CREATE TABLE eam_maintenance_item_spare (tenant_id BIGINT NOT NULL,standard_id BIGINT NOT NULL,item_key VARCHAR(128) NOT NULL,sort_no INT NOT NULL,stock_id BIGINT NOT NULL COMMENT '原备件库存ID',quantity DECIMAL(18,2) NOT NULL COMMENT '要求数量',PRIMARY KEY(tenant_id,standard_id,item_key,sort_no),FOREIGN KEY(tenant_id,standard_id,item_key) REFERENCES eam_maintenance_standard_item(tenant_id,standard_id,item_key) ON DELETE CASCADE) COMMENT='保养项目spare明细';

INSERT INTO eam_maintenance_item_spare SELECT d.tenant_id,d.id,JSON_UNQUOTE(JSON_EXTRACT(j.item,'$.id')),v.sort_no,JSON_UNQUOTE(JSON_EXTRACT(v.value,'$.stockId')),JSON_EXTRACT(v.value,'$.quantity') FROM eam_maintenance_definition d JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(d.payload,'$.items'),JSON_ARRAY()),'$[*]' COLUMNS(item JSON PATH '$')) j JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(j.item,'$.spareRequirements'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,value JSON PATH '$')) v WHERE d.kind='standards';

CREATE TABLE eam_maintenance_plan_device (id BIGINT NOT NULL,tenant_id BIGINT NOT NULL,plan_id BIGINT NOT NULL,equipment_id BIGINT NOT NULL,type_id BIGINT NOT NULL,next_date DATE NOT NULL,anchor_date DATE NOT NULL,cycle_index INT NOT NULL DEFAULT 0,enabled TINYINT NOT NULL DEFAULT 1,`period_count` INT NOT NULL COMMENT '周期数',`period_unit` VARCHAR(8) NOT NULL COMMENT '周期单位',`valid_days` INT NOT NULL COMMENT '任务有效天数',`remark` TEXT NOT NULL COMMENT '说明',PRIMARY KEY(id),INDEX ix_maintenance_plan_device_due(enabled,next_date),INDEX ix_maintenance_plan_device_plan(tenant_id,plan_id)) COMMENT='保养计划设备及周期调度';

INSERT INTO eam_maintenance_plan_device SELECT id,tenant_id,plan_id,equipment_id,type_id,next_date,anchor_date,cycle_index,enabled,COALESCE(CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.period')),'null'),'') AS SIGNED),1),COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.unit')),'null'),''),'月'),COALESCE(CAST(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.validDays')),'null'),'') AS SIGNED),0),COALESCE(NULLIF(NULLIF(JSON_UNQUOTE(JSON_EXTRACT(payload,'$.remark')),'null'),''),'') FROM eam_maintenance_schedule;

CREATE TABLE eam_maintenance_device_person (tenant_id BIGINT NOT NULL,device_id BIGINT NOT NULL,role_code VARCHAR(16) NOT NULL,user_id BIGINT NOT NULL,sort_no INT NOT NULL,PRIMARY KEY(tenant_id,device_id,role_code,user_id),FOREIGN KEY(device_id) REFERENCES eam_maintenance_plan_device(id) ON DELETE CASCADE) COMMENT='计划设备person关联';

INSERT INTO eam_maintenance_device_person SELECT s.tenant_id,s.id,'owner',j.user_id,MIN(j.sort_no) FROM eam_maintenance_schedule s JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(s.payload,'$.owners'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,user_id BIGINT PATH '$' ERROR ON ERROR)) j GROUP BY s.tenant_id,s.id,j.user_id;

INSERT INTO eam_maintenance_device_person SELECT s.tenant_id,s.id,'reviewer',j.user_id,MIN(j.sort_no) FROM eam_maintenance_schedule s JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(s.payload,'$.reviewers'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,user_id BIGINT PATH '$' ERROR ON ERROR)) j GROUP BY s.tenant_id,s.id,j.user_id;

CREATE TABLE eam_maintenance_device_project (tenant_id BIGINT NOT NULL,device_id BIGINT NOT NULL,standard_id BIGINT NOT NULL,item_key VARCHAR(128) NOT NULL,sort_no INT NOT NULL,PRIMARY KEY(tenant_id,device_id,standard_id,item_key),FOREIGN KEY(device_id) REFERENCES eam_maintenance_plan_device(id) ON DELETE CASCADE) COMMENT='计划设备project关联';

INSERT INTO eam_maintenance_device_project SELECT s.tenant_id,s.id,j.standard_id,j.item_key,MIN(j.sort_no) FROM eam_maintenance_schedule s JOIN JSON_TABLE(COALESCE(JSON_EXTRACT(s.payload,'$.projectRefs'),JSON_ARRAY()),'$[*]' COLUMNS(sort_no FOR ORDINALITY,standard_id BIGINT PATH '$.standardId',item_key VARCHAR(128) PATH '$.itemId')) j GROUP BY s.tenant_id,s.id,j.standard_id,j.item_key;

CREATE VIEW v_maintenance_item AS SELECT i.*, JSON_OBJECT('id',i.item_key,'code',i.`code`,'module',i.`module_name`,'name',i.`name`,'content',i.`content`,'typeId',COALESCE(CAST(i.`type_id` AS CHAR),''),'valueType',i.`value_type`,'lower',COALESCE(CAST(i.`lower_bound` AS CHAR),''),'upper',COALESCE(CAST(i.`upper_bound` AS CHAR),''),'required',IF(i.`required`=1,CAST('true' AS JSON),CAST('false' AS JSON)),'photoRequired',IF(i.`photo_required`=1,CAST('true' AS JSON),CAST('false' AS JSON)),'remark',i.`remark`,'spares',i.`spare_description`,'options',COALESCE((SELECT JSON_ARRAYAGG(r.option_value) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_maintenance_item_option r WHERE r.tenant_id=i.tenant_id AND r.standard_id=i.standard_id AND r.item_key=i.item_key LIMIT 1),JSON_ARRAY()),'normalOptions',COALESCE((SELECT JSON_ARRAYAGG(r.option_value) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_maintenance_item_option r WHERE r.tenant_id=i.tenant_id AND r.standard_id=i.standard_id AND r.item_key=i.item_key AND r.normal_value=1 LIMIT 1),JSON_ARRAY()),'references',COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('id',r.file_id,'name',r.name_snapshot,'contentType',r.content_type,'size',r.size_bytes,'url',r.url_snapshot)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_maintenance_item_file r WHERE r.tenant_id=i.tenant_id AND r.standard_id=i.standard_id AND r.item_key=i.item_key LIMIT 1),JSON_ARRAY()),'spareRequirements',COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('stockId',CAST(r.stock_id AS CHAR),'quantity',r.quantity)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_maintenance_item_spare r WHERE r.tenant_id=i.tenant_id AND r.standard_id=i.standard_id AND r.item_key=i.item_key LIMIT 1),JSON_ARRAY())) AS item_view FROM eam_maintenance_standard_item i;

CREATE VIEW v_maintenance_schedule AS SELECT d.*, COALESCE((SELECT r.standard_id FROM eam_maintenance_device_project r WHERE r.tenant_id=d.tenant_id AND r.device_id=d.id ORDER BY r.sort_no LIMIT 1),0) AS standard_id,JSON_OBJECT('id',CAST(d.id AS CHAR),'equipmentId',CAST(d.equipment_id AS CHAR),'typeId',CAST(d.type_id AS CHAR),'nextDate',DATE_FORMAT(d.next_date,'%Y-%m-%d'),'period',d.`period_count`,'unit',d.`period_unit`,'validDays',d.`valid_days`,'remark',d.`remark`,'owners',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_maintenance_device_person r WHERE r.tenant_id=d.tenant_id AND r.device_id=d.id AND r.role_code='owner' LIMIT 1),JSON_ARRAY()),'reviewers',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_maintenance_device_person r WHERE r.tenant_id=d.tenant_id AND r.device_id=d.id AND r.role_code='reviewer' LIMIT 1),JSON_ARRAY()),'projectRefs',COALESCE((SELECT JSON_ARRAYAGG(JSON_OBJECT('standardId',CAST(r.standard_id AS CHAR),'itemId',r.item_key)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_maintenance_device_project r WHERE r.tenant_id=d.tenant_id AND r.device_id=d.id LIMIT 1),JSON_ARRAY()),'standardId',CAST(COALESCE((SELECT r.standard_id FROM eam_maintenance_device_project r WHERE r.tenant_id=d.tenant_id AND r.device_id=d.id ORDER BY r.sort_no LIMIT 1),0) AS CHAR)) AS payload FROM eam_maintenance_plan_device d;

CREATE VIEW v_maintenance_definition AS SELECT d.id,d.tenant_id,'types' kind,d.code,d.name,d.department_id,d.creator_id,d.row_version,d.created_at,d.updated_at,JSON_OBJECT('period',d.`period_count`,'unit',d.`period_unit`,'symbol',d.`symbol`,'system',IF(d.`is_system`=1,CAST('true' AS JSON),CAST('false' AS JSON)),'enabled',IF(d.`enabled`=1,CAST('true' AS JSON),CAST('false' AS JSON)),'remark',d.`remark`,'items',JSON_ARRAY(),'equipmentIds',JSON_ARRAY(),'categoryIds',JSON_ARRAY(),'categoryNames',JSON_ARRAY(),'legacyCategoryNames',JSON_ARRAY(),'owners',JSON_ARRAY(),'reviewers',JSON_ARRAY(),'details',JSON_ARRAY()) payload FROM eam_maintenance_type d UNION ALL SELECT d.id,d.tenant_id,'standards' kind,d.code,d.name,d.department_id,d.creator_id,d.row_version,d.created_at,d.updated_at,JSON_OBJECT('enabled',IF(d.`enabled`=1,CAST('true' AS JSON),CAST('false' AS JSON)),'remark',d.`remark`,'items',COALESCE((SELECT JSON_ARRAYAGG(r.item_view) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM v_maintenance_item r WHERE r.tenant_id=d.tenant_id AND r.standard_id=d.id LIMIT 1),JSON_ARRAY()),'equipmentIds',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.equipment_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_maintenance_standard_equipment r WHERE r.tenant_id=d.tenant_id AND r.standard_id=d.id LIMIT 1),JSON_ARRAY()),'categoryIds',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.category_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_maintenance_standard_category r WHERE r.tenant_id=d.tenant_id AND r.standard_id=d.id LIMIT 1),JSON_ARRAY()),'categoryNames',COALESCE((SELECT JSON_ARRAYAGG(r.name_snapshot) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_maintenance_standard_category_label r WHERE r.tenant_id=d.tenant_id AND r.standard_id=d.id AND r.label_kind='display' LIMIT 1),JSON_ARRAY()),'legacyCategoryNames',COALESCE((SELECT JSON_ARRAYAGG(r.name_snapshot) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_maintenance_standard_category_label r WHERE r.tenant_id=d.tenant_id AND r.standard_id=d.id AND r.label_kind='legacy' LIMIT 1),JSON_ARRAY()),'owners',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_maintenance_standard_person r WHERE r.tenant_id=d.tenant_id AND r.standard_id=d.id AND r.role_code='owner' LIMIT 1),JSON_ARRAY()),'reviewers',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_maintenance_standard_person r WHERE r.tenant_id=d.tenant_id AND r.standard_id=d.id AND r.role_code='reviewer' LIMIT 1),JSON_ARRAY()),'details',JSON_ARRAY()) payload FROM eam_maintenance_standard d UNION ALL SELECT d.id,d.tenant_id,'plans' kind,d.code,d.name,d.department_id,d.creator_id,d.row_version,d.created_at,d.updated_at,JSON_OBJECT('enabled',IF(d.`enabled`=1,CAST('true' AS JSON),CAST('false' AS JSON)),'remark',d.`remark`,'calculation',d.`calculation_mode`,'advanceDays',d.`advance_days`,'remindDays',d.`remind_days`,'autoFill',d.`auto_fill`,'scanStart',IF(d.`scan_start`=1,CAST('true' AS JSON),CAST('false' AS JSON)),'reviewMode',d.`review_mode`,'reviewRule',d.`review_rule`,'items',JSON_ARRAY(),'equipmentIds',JSON_ARRAY(),'categoryIds',JSON_ARRAY(),'categoryNames',JSON_ARRAY(),'legacyCategoryNames',JSON_ARRAY(),'owners',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_maintenance_plan_person r WHERE r.tenant_id=d.tenant_id AND r.plan_id=d.id AND r.role_code='owner' LIMIT 1),JSON_ARRAY()),'reviewers',COALESCE((SELECT JSON_ARRAYAGG(CAST(r.user_id AS CHAR)) OVER(ORDER BY r.sort_no ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM eam_maintenance_plan_person r WHERE r.tenant_id=d.tenant_id AND r.plan_id=d.id AND r.role_code='reviewer' LIMIT 1),JSON_ARRAY()),'details',COALESCE((SELECT JSON_ARRAYAGG(r.payload) OVER(ORDER BY r.id ROWS BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) FROM v_maintenance_schedule r WHERE r.tenant_id=d.tenant_id AND r.plan_id=d.id AND r.enabled=1 LIMIT 1),JSON_ARRAY())) payload FROM eam_maintenance_plan d;

ALTER TABLE eam_maintenance_task DROP FOREIGN KEY fk_maintenance_task_type;

ALTER TABLE eam_maintenance_task ADD CONSTRAINT fk_maintenance_task_type_v67 FOREIGN KEY(type_id) REFERENCES eam_maintenance_type(id);

RENAME TABLE eam_maintenance_definition TO migration_v67_maintenance_definition_archive,eam_maintenance_schedule TO migration_v67_maintenance_schedule_archive;
